import{_ as t,o as l,c as e,a2 as r}from"./chunks/framework.DnrXFDHb.js";const p=JSON.parse('{"title":"常用工具","description":"","frontmatter":{},"headers":[],"relativePath":"tools/common-tools.md","filePath":"tools/common-tools.md","lastUpdated":1788308924000}'),i={name:"tools/common-tools.md"};function o(d,a,n,h,s,u){return l(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="常用工具" tabindex="-1">常用工具 <a class="header-anchor" href="#常用工具" aria-label="Permalink to &quot;常用工具&quot;">​</a></h1><blockquote><p><strong>一句话结论：</strong> 工具把模型能力包装成可用产品，但能力始终来自模型；零基础起步只需要“一个对话助手、一个绘画入口、一次本地运行尝试”，每类先用熟一个稳定的，再按真实需求扩展，不追新、不囤积。</p></blockquote><p>本页链接与描述核对于 2026 年 9 月；工具与平台迭代较快，使用前请以官方页面为准。</p><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li>已阅读 <a href="/llm/basics">大模型入门</a>，知道模型与工具的分工：工具负责调用与包装，能力来自模型。</li><li>已阅读 <a href="/concepts/base-model">底模是什么</a>，知道 AI 绘画工具加载的是模型文件。</li><li>先接受一个边界：工具和功能更新很快，本页只收录多年稳定存在、官方可信的工具并描述定位，不写版本号、价格和排行榜。</li><li><strong>本页不涉及</strong>：各工具的安装排障与具体版本配置；遇到问题优先查阅工具的官方文档。</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>读完后，你应该能够：</p><ul><li>按用途说出五类工具各自解决什么问题、适合谁。</li><li>为第一周的尝试选出一套最小工具组合，并说明理由。</li><li>判断一个任务该用网页工具、本地部署还是 API。</li><li>对比云端网页工具与本地部署在门槛、隐私和可控性上的差异。</li><li>识别“囤积工具”“追新”这两类常见的时间陷阱。</li></ul><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="对话与编程助手-先用好一个" tabindex="-1">对话与编程助手：先用好一个 <a class="header-anchor" href="#对话与编程助手-先用好一个" aria-label="Permalink to &quot;对话与编程助手：先用好一个&quot;">​</a></h3><p>先看结构版图：对话模型分两类——闭源 API 模型（通过官方网页或 API 使用，拿不到模型文件）与开放权重模型（常被泛称为开源模型，可下载到本地跑）。中文用户常接触 Qwen、DeepSeek 等国产开放权重系列，英文生态里常见 Llama 等。粗选时看三点：对你所用语言（如中文）的能力、许可证是否允许你的用途、以及打算本地跑还是云端跑。</p><p>ChatGPT、Claude、Gemini 等网页对话助手是大多数人的第一个 AI 工具：打开网页就能问答、写作、翻译、总结和初步分析文件。GitHub Copilot 一类编程助手把同类能力嵌进代码编辑器，边写边补全和解释。</p><ul><li>适合：零基础验证想法、处理一次性任务、日常问答与写作。</li><li>注意：不要上传无权处理的隐私、商业机密或受限制的数据；平台的数据使用条款和内容规则会更新，使用前看一眼当前版本。</li><li>起步：先用网页版完成一个小任务，确认需求后再考虑 API 或付费方案，不必一上来就研究接口。</li><li>边界：回答流畅不代表正确，重要结论仍要人工核对；模型本身的知识截止与幻觉局限并不会因为换工具而消失。</li></ul><h3 id="图像生成工具-网页平台与节点式工具" tabindex="-1">图像生成工具：网页平台与节点式工具 <a class="header-anchor" href="#图像生成工具-网页平台与节点式工具" aria-label="Permalink to &quot;图像生成工具：网页平台与节点式工具&quot;">​</a></h3><p>按投入程度从低到高：</p><ul><li><strong>网页图像平台</strong>：各模型官方或合作方提供的在线生成服务，不需要本地显卡，适合快速体验文生图、确认自己是否有长期兴趣。</li><li><strong>Stable Diffusion WebUI</strong>：按钮式本地界面，适合跟随大多数传统教程、使用成熟的插件生态完成常见的图生图操作。</li><li><strong>ComfyUI</strong>：节点式本地界面，把生成流程拆成可自由连接的节点，适合理解模型数据流、精细控制和复用工作流（见 <a href="/workflows/workflow-vs-template">工作流和模板区别</a>）。</li></ul><p>适合想认真玩 AI 绘画、需要精细控制和可复现流程的人。本地工具的性能取决于显卡与模型生态的匹配：选底模和插件之前，先读 <a href="/models/ecosystems">常见模型生态</a>。另外，AI 出图之后通常仍需要裁剪、调色、瑕疵修复和放大，可配合 Photoshop、Krita、GIMP 等多年稳定的图像编辑工具完成；公开发布前保留来源记录并做人工筛选。</p><h3 id="本地运行开源模型-ollama-与同类" tabindex="-1">本地运行开源模型：Ollama 与同类 <a class="header-anchor" href="#本地运行开源模型-ollama-与同类" aria-label="Permalink to &quot;本地运行开源模型：Ollama 与同类&quot;">​</a></h3><p>Ollama、LM Studio、llama.cpp 可以在自己电脑上下载和运行开源模型（通常是量化后的版本；量化：用更低精度的数字存储模型参数，换取更小显存占用），数据不出本机。</p><ul><li>适合：在意隐私、需要离线使用，或者想直观感受“模型就是一个大文件”的学习者。</li><li>注意：本地效果受硬件与量化损失限制，不一定追平云端最强模型；开源不等于可以随意商用，模型许可证仍然要核对。</li><li>起步：从社区验证过的小参数量模型试起，先跑通流程，再考虑更大的模型。</li><li>边界：本地跑通不等于会用——模型怎么选、参数什么含义，仍要回到本站的原理页补概念。</li></ul><h3 id="rag-与知识库搭建-从现成功能到框架" tabindex="-1">RAG 与知识库搭建：从现成功能到框架 <a class="header-anchor" href="#rag-与知识库搭建-从现成功能到框架" aria-label="Permalink to &quot;RAG 与知识库搭建：从现成功能到框架&quot;">​</a></h3><p>想“针对自己的资料提问”，路径是递进的：先用对话助手自带的文件上传或现成笔记软件的 AI 功能，验证需求是否真实存在；确有定制需要时，再考虑 LangChain、LlamaIndex 这类检索增强（RAG）框架，或 Dify 这类低代码平台（原理见 <a href="/llm/rag-agent">RAG 与 Agent</a>）。</p><p>如果要把模型能力接进自己的程序，则通过 API 与 SDK 调用，用于分类、信息抽取、结构化输出、问答和工具调用等固定流程。除了“能调通”，实际项目还要处理：</p><ul><li>密钥和权限管理。</li><li>请求超时、限流、重试和错误记录。</li><li>输入输出校验，特别是 JSON 与 Function Calling 参数。</li><li>成本、延迟、模型版本和回归评估。</li><li>敏感数据脱敏与审计。</li></ul><p>框架和 API 能减少重复开发，但解决不了文档质量、切分方式和检索效果这些核心问题。API 调用成功只代表请求完成，不代表结果已经正确。</p><h3 id="学习平台-模型卡与官方课程" tabindex="-1">学习平台：模型卡与官方课程 <a class="header-anchor" href="#学习平台-模型卡与官方课程" aria-label="Permalink to &quot;学习平台：模型卡与官方课程&quot;">​</a></h3><ul><li><strong>Hugging Face</strong>：开源模型与数据集的主要集散地；读模型卡（Model Card）是使用任何模型前的第一步。</li><li><strong>Google 机器学习课程</strong>：官方出品的系统课程，负责在动手前补齐概念。</li><li><strong>Hugging Face LLM Course</strong>：掌握基础概念后，继续深入原理与实践。</li></ul><p>工具的界面年年变，平台和课程稳定得多。完整清单见 <a href="/resources/websites">常用网站</a>，进阶教程见 <a href="/resources/tutorials">精选教程</a>。</p><h2 id="动手试试-第一个工具组合" tabindex="-1">动手试试：第一个工具组合 <a class="header-anchor" href="#动手试试-第一个工具组合" aria-label="Permalink to &quot;动手试试：第一个工具组合&quot;">​</a></h2><p>第一周不建议同时开五六个工具。一套覆盖三条理解路径的最小组合：</p><table tabindex="0"><thead><tr><th>用途</th><th>起点建议</th><th>一句理由</th></tr></thead><tbody><tr><td>对话</td><td>任一主流网页对话助手</td><td>零门槛，当天就能验证本站讲的 Token、幻觉这些概念</td></tr><tr><td>绘画</td><td>一个网页图像平台</td><td>不依赖本地显卡，先确认兴趣，再决定要不要装 ComfyUI</td></tr><tr><td>本地尝试</td><td>用 Ollama 跑一个开源小模型</td><td>一条命令体验“模型在自己电脑上”，建立模型即文件的直觉</td></tr></tbody></table><p>第一周的行动顺序：</p><ol><li>用对话助手照着 <a href="/prompting/basics">Prompt 入门</a> 的六要素写几条任务说明，感受结构化写法与随手一问的差别。</li><li>在绘画平台用同一句提示词只换风格词，观察模型如何响应。</li><li>用 Ollama 跑通一个小模型，问它一件训练截止之后发生的事，亲眼看到知识截止。</li><li>把三条路径的体会各记一句话——记录比工具本身更保值。</li></ol><p>随着工具用起来，建议记录：模型名称、来源和许可证；模型卡里的推荐参数；自己验证过的 Prompt 与参数组合；遇到过的失败模式。以后排查问题时，先查这份清单。</p><p>搭配原则：每类先用熟一个，遇到真实瓶颈（隐私、离线、精细控制、规模化）再引入第二个工具。组合没有唯一正解，稳定和够用比多更重要。</p><h2 id="对比表" tabindex="-1">对比表 <a class="header-anchor" href="#对比表" aria-label="Permalink to &quot;对比表&quot;">​</a></h2><p>云端与本地不是二选一，而是同一张地图上的两端：</p><table tabindex="0"><thead><tr><th>维度</th><th>云端网页工具</th><th>本地部署</th></tr></thead><tbody><tr><td>上手门槛</td><td>注册即用，无硬件要求</td><td>需要安装配置和一定硬件</td></tr><tr><td>成本形态</td><td>订阅或按量付费</td><td>硬件与电费为主，模型多为开源</td></tr><tr><td>隐私</td><td>数据交给服务商，取决于平台条款</td><td>数据不出本机</td></tr><tr><td>可控性</td><td>模型版本与功能由平台决定</td><td>模型、参数、更新节奏自己控制</td></tr><tr><td>能力上限</td><td>通常能用上最强模型</td><td>受本地硬件与量化损失限制</td></tr><tr><td>维护负担</td><td>平台负责更新与运维</td><td>升级、排错、环境管理都靠自己</td></tr><tr><td>适用人群</td><td>零基础体验与日常使用</td><td>重隐私、需离线、想弄懂原理的学习者</td></tr></tbody></table><p>费用形态上，云端工具多为订阅制或按用量计费，本地部署主要成本是一次性硬件与电费；API 类服务通常把输入与输出分开按 Token 计价，长上下文会显著放大费用。</p><p>很多人的实际路径是：日常用云端，涉及敏感资料或想学原理时转本地。选哪端，先看任务对隐私和可控性的要求，再看自己的硬件和时间预算。</p><p>按任务快速对号入座：</p><ul><li>一次性体验、随手一问：网页对话助手或网页图像平台。</li><li>固定的应用流程（分类、抽取、结构化输出）：API，并建立日志、校验和评估。</li><li>隐私或离线要求：本地运行开源模型，先评估硬件成本。</li><li>经常查询自有资料：先做简单 RAG 验证需求，再考虑 Agent 框架。</li><li>需要精细图像控制：Stable Diffusion WebUI 或 ComfyUI，并保留可复现的工作流。</li></ul><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li><strong>“工具越多越好”</strong>：工具只负责调用，能力来自模型；概念没搞清之前囤积工具，只会在界面之间迷路。</li><li><strong>“新工具一出就该换掉旧的”</strong>：新工具迭代快、寿命不定；优先用多年稳定存在的，等新工具有了清晰定位再试不迟。</li><li><strong>“本地模型一定更安全、更好”</strong>：本地解决的是数据不出本机的问题，不改变模型本身的能力上限，也不豁免许可证约束。</li><li><strong>“API 调用成功就等于结果正确”</strong>：请求完成只代表链路通了，内容仍要做校验和评估。</li><li><strong>“RAG 框架装好就有知识库”</strong>：文档切分、检索质量和来源管理才是难点，框架只是脚手架。</li><li><strong>“平台功能等于模型能力”</strong>：联网搜索、文件分析是工具层的功能，模型本身的知识截止和局限并没有变。</li></ul><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><h3 id="_1-第一周只配-一个对话助手-一个网页绘画平台-一次本地运行-为什么这么配" tabindex="-1">1. 第一周只配“一个对话助手 + 一个网页绘画平台 + 一次本地运行”，为什么这么配？ <a class="header-anchor" href="#_1-第一周只配-一个对话助手-一个网页绘画平台-一次本地运行-为什么这么配" aria-label="Permalink to &quot;1. 第一周只配“一个对话助手 + 一个网页绘画平台 + 一次本地运行”，为什么这么配？&quot;">​</a></h3><details><summary>查看答案</summary><p>三类工具覆盖三条最低成本的理解路径：对话助手验证语言模型的能力与局限，网页绘画确认自己是否有兴趣，本地运行建立“模型是文件、可以自己跑”的直觉。每类只选一个，是为了把时间花在概念上而不是工具切换上。</p></details><h3 id="_2-要求-内部资料不能上传到任何云端-应该选哪类工具-要注意什么" tabindex="-1">2. 要求“内部资料不能上传到任何云端”，应该选哪类工具？要注意什么？ <a class="header-anchor" href="#_2-要求-内部资料不能上传到任何云端-应该选哪类工具-要注意什么" aria-label="Permalink to &quot;2. 要求“内部资料不能上传到任何云端”，应该选哪类工具？要注意什么？&quot;">​</a></h3><details><summary>查看答案</summary><p>选本地运行开源模型的工具（如 Ollama、LM Studio），数据不出本机。要注意：本地硬件是否带得动目标模型、模型许可证是否允许你的用途，以及本地小模型的效果通常低于云端最强模型，复杂任务要先做评估。</p></details><h3 id="_3-新出的工具要不要马上换掉现在用的-怎么判断" tabindex="-1">3. “新出的工具要不要马上换掉现在用的？”怎么判断？ <a class="header-anchor" href="#_3-新出的工具要不要马上换掉现在用的-怎么判断" aria-label="Permalink to &quot;3. “新出的工具要不要马上换掉现在用的？”怎么判断？&quot;">​</a></h3><details><summary>查看答案</summary><p>默认不换。判断标准：新工具是否已稳定存在一段时间、是否解决了你现在的真实瓶颈、迁移成本多大。如果现在的工具够用，追新消耗的是学习概念和积累经验的时间；真有瓶颈时，也先在旧工具里确认问题无法解决再迁移。</p></details><h2 id="下一步阅读" tabindex="-1">下一步阅读 <a class="header-anchor" href="#下一步阅读" aria-label="Permalink to &quot;下一步阅读&quot;">​</a></h2><ul><li>上一篇：<a href="/workflows/workflow-vs-template">工作流和模板区别</a>：工具承载的流程，先分清模板与工作流。</li><li>下一篇：<a href="/resources/websites">常用网站</a>：按本页的工具分类找官方文档与学习资源。</li><li>相关阅读：<a href="/resources/tutorials">精选教程</a>：选定工具后的系统学习入口。</li><li>相关阅读：<a href="/glossary">术语表</a>：使用工具时遇到生词随时回查。</li></ul><h2 id="官方或原始资料来源" tabindex="-1">官方或原始资料来源 <a class="header-anchor" href="#官方或原始资料来源" aria-label="Permalink to &quot;官方或原始资料来源&quot;">​</a></h2><ul><li><a href="https://openai.com" target="_blank" rel="noreferrer">OpenAI（ChatGPT）</a>：ChatGPT 与其 API 的官方站点。</li><li><a href="https://www.anthropic.com" target="_blank" rel="noreferrer">Anthropic（Claude）</a>：Claude 的官方站点与文档入口。</li><li><a href="https://gemini.google.com" target="_blank" rel="noreferrer">Google（Gemini）</a>：Gemini 官方入口。</li><li><a href="https://ollama.com" target="_blank" rel="noreferrer">Ollama</a>：本地运行开源模型的官方站点与文档。</li><li><a href="https://github.com/Comfy-Org/ComfyUI" target="_blank" rel="noreferrer">ComfyUI 官方仓库</a>：节点式绘画工具的官方代码仓库。</li><li><a href="https://huggingface.co" target="_blank" rel="noreferrer">Hugging Face</a>：开源模型、数据集与模型卡的官方平台。</li></ul>',55)])])}const c=t(i,[["render",o]]);export{p as __pageData,c as default};
